from hdr import *
r.append(R(7454682,"मटन (मेमने) की बिरयानी",
"एक बढ़िया एशियाई व्यंजन, जो मेहमानों के स्वागत और खास मौकों के लिए आदर्श है।",
"6","394 ग्राम",
["1 बड़ा चम्मच तेल","4 प्याज़, कटे हुए","750 ग्राम बिना हड्डी की मेमने की टाँग, टुकड़ों में कटी हुई","4 फांक लहसुन, कुचला हुआ","1.5 छोटे चम्मच ताज़ा अदरक, छिला और कद्दूकस किया हुआ","1 डंडी दालचीनी","3 इलायची की फलियाँ","8 लौंग","8 काली मिर्च के दाने","1 बड़ा चम्मच मिर्च पाउडर","1 बड़ा चम्मच पिसा धनिया","1 x 150 ग्राम का डिब्बा कम वसा वाला सादा दही","1/2 छोटा चम्मच केसर, 3 बड़े चम्मच उबलते पानी में भिगोया हुआ","450 ग्राम बासमती चावल, पैकेट पर दिए निर्देशों के अनुसार पकाया हुआ"],
["एक बड़े पैन में तेल गरम करें, प्याज़ डालें और 3-4 मिनट हल्का सुनहरा होने तक भूनें। 1/4 प्याज़ निकालकर अलग रख दें।","मेमना, लहसुन, अदरक, दालचीनी की डंडी, इलायची, लौंग और काली मिर्च के दाने पैन में डालें और 8-10 मिनट भूनें, जब तक मेमना चारों ओर से हल्का भूरा न हो जाए।","मिर्च पाउडर और पिसे धनिए को 2 बड़े चम्मच उबलते पानी में घोलें, फिर पैन में डालें। पैन को ढक दें और माँस को धीमी आँच पर पकाएँ। 40-45 मिनट तक पकाएँ, जब तक माँस नरम न हो जाए।","ओवन को 150ºC/गैस 2 पर पहले से गरम करें। पैन में दही डालें और चलाएँ। इसी बीच, अलग रखा हुआ प्याज़ एक पैन में रखें और 5-6 मिनट और भूनें, जब तक गहरा भूरा न हो जाए।","1/3 चावल एक भारी कैसरोल डिश की तली में रखें, ऊपर थोड़ा केसर का मिश्रण छिड़कें। उसके ऊपर माँस के मिश्रण की आधी परत बिछाएँ और 1/3 और चावल से ढकें और थोड़ा केसर का मिश्रण छिड़कें। इसे दोहराएँ, आख़िर में चावल की परत रखें और केसर छिड़कें। हल्का दबाएँ। ऊपर भुना हुआ प्याज़ रखें।","पैन को कसकर बंद होने वाले ढक्कन से ढकें और 10 मिनट पकाएँ। ओवन से निकालें, ताज़ा धनिया छिड़कें और परोसें।"],
["आप इस व्यंजन के लिए चिकन या पोर्क इस्तेमाल कर सकते हैं।","शाकाहारी संस्करण के लिए, मेमने की जगह शिमला मिर्च, बैंगन और मशरूम जैसी कटी हुई सब्ज़ियों का मिश्रण डालें। चावल में मिलाने से पहले उन्हें केवल 5 मिनट पकाना होगा।","फ्रीज़ करने के निर्देश: पकने के बाद फ्रीज़ करने के लिए उपयुक्त। जल्दी ठंडा करें। फ्रिज में डीफ़्रॉस्ट करें और अंदर तक अच्छी तरह गरम होने तक दोबारा गरम करें। तुरंत खाएँ और बचा हुआ कुछ भी फेंक दें।",fv(1)]))
r.append(R(7456468,"सेब और म्यूज़ली स्मूदी",
"नाश्ते के अनाज का एक मज़ेदार और पेट भरने वाला विकल्प, जो पौष्टिकता से भरपूर है।",
"1","345 ग्राम",
["1 सेब, छिला हुआ, बीज निकालकर कटा हुआ (100 ग्राम)","20 ग्राम बिना अतिरिक्त चीनी वाली म्यूज़ली","125 ग्राम सादा ग्रीक दही","100 मिलीलीटर सेमी-स्किम्ड दूध"],
["बस सारी सामग्री को फूड प्रोसेसर/ब्लेंडर में डालें और चिकना होने तक ब्लेंड करें।","तुरंत परोसें।"],
["अपनी म्यूज़ली को रात भर भीगने दें, फिर ब्लेंड करने से पहले दही और सेब मिलाएँ।","यह स्मूदी सेब की जगह नाशपाती के साथ भी बहुत स्वादिष्ट लगती है।",fv(1)]))
r.append(R(7459232,"भुनी सब्ज़ियों के साथ पोलेंटा",
"परिवार के लिए एकदम सही आरामदायक व्यंजन।",
"4","405 ग्राम",
["2 बड़े चम्मच ऑलिव ऑयल","2 लाल प्याज़, छिले हुए और फाँकों में कटे हुए","1 लाल, 1 पीली और 1 हरी शिमला मिर्च, बीज निकालकर हर एक के 8 टुकड़ों में कटी हुई","2 तोरी (कूजेट), लंबाई में चार टुकड़ों में, फिर 4 सेमी लंबाई में कटी हुई","800 मिलीलीटर उबलता पानी","200 ग्राम पोलेंटा","400 ग्राम डिब्बाबंद चेरी टमाटर","2–3 फांक लहसुन, कुचला हुआ","1 ढेर वाला छोटा चम्मच सूखा ओरेगैनो","एक चुटकी मिर्च के गुच्छे (चिली फ्लेक्स)","मुट्ठी भर ताज़ी तुलसी की पत्तियाँ, परोसने के लिए"],
["ओवन को 200°C/गैस 6 पर पहले से गरम करें। 1 1/2 बड़े चम्मच ऑलिव ऑयल को प्याज़, शिमला मिर्च और तोरी के साथ एक कटोरे में डालें। अच्छी तरह मिलाएँ, बेकिंग ट्रे पर फैलाएँ और 25-30 मिनट भूनें।","इसी बीच, एक बड़े पैन में उबलता पानी डालें और धीरे-धीरे पोलेंटा मिलाएँ, लकड़ी के चम्मच से लगभग 5 मिनट चलाते रहें। फिर इसे हल्का तेल लगी 2 पाउंड की लोफ़ टिन (लगभग 22 सेमी x 11 सेमी) में डालें, और ऊपरी सतह को चम्मच के पिछले हिस्से से समतल करें। 5 मिनट के लिए एक तरफ़ रख दें।","डिब्बाबंद टमाटर, लहसुन, ओरेगैनो और मिर्च के गुच्छे एक पैन में डालें, एक साथ चलाएँ और 5 मिनट धीमी आँच पर पकाएँ।","पोलेंटा को चॉपिंग बोर्ड पर उलटकर निकालें और 1 1/2 सेमी मोटे स्लाइस में काटें, फिर गरम ग्रिल पैन पर या ग्रिल के नीचे हर तरफ़ लगभग 3-4 मिनट हल्का सुनहरा होने तक पकाएँ।","परोसने के लिए, पोलेंटा के एक स्लाइस पर टमाटर और जड़ी-बूटी की सॉस का एक चम्मच डालें, ऊपर कुछ भुनी सब्ज़ियाँ बिखेरें और कुछ ताज़ी तुलसी की पत्तियों से सजाएँ। यदि चाहें तो मुट्ठी भर कद्दूकस किया चीज़ डालें।"],
["इस व्यंजन का अलग रूप बनाने के लिए अपनी पसंद की कोई भी सब्ज़ियाँ इस्तेमाल करें। बैंगन और मशरूम अच्छे रहते हैं।","फ्रीज़ करने के निर्देश: पोलेंटा और सब्ज़ियों को अलग-अलग फ्रीज़ करें। फिर फ्रिज या माइक्रोवेव में डीफ़्रॉस्ट करें और अंदर तक गरम होने तक दोबारा गरम करें।",fv(3)]))
r.append(R(7459708,"फ्रोज़न योगर्ट बार्क",
"गर्मियों की बेरीज़ बिखेरकर मौसमी ट्रीट का आनंद लें। यह रेसिपी स्लिमिंग वर्ल्ड के साथ साझेदारी में चुनी गई थी।",
"4","100 ग्राम",
["250 ग्राम वसा रहित बिना मीठा सादा दही","150 ग्राम ताज़ी स्ट्रॉबेरी, रास्पबेरी और ब्लूबेरी, स्ट्रॉबेरी का डंठल निकालकर कटी हुई"],
["एक चौड़ी बेकिंग ट्रे में बेकिंग पेपर बिछाएँ। बेकिंग पेपर पर दही के चम्मच डालें, फिर स्पैचुला या चम्मच से उसे बराबर फैलाएँ, ताकि वह लगभग 1 सेमी मोटा हो जाए।","ऊपर से बेरीज़ को बराबर बिखेरें, फिर कम से कम 3 घंटे के लिए फ्रीज़ करें, या जब तक बार्क पूरी तरह ठोस न हो जाए।","जब बार्क खाने के लिए तैयार हो, तो इसे कमरे के तापमान पर 5 मिनट रखें ताकि थोड़ा नरम हो जाए, फिर परोसने के लिए टुकड़ों में तोड़ लें।"],
[fv(0)]))
